using System.Collections.Generic;
using UnityEngine;

namespace Manjong.UI
{
    /// <summary>
    /// Painted table textures from Resources/Table/&lt;name&gt;.png (generated by tools/render_table.py): felt, felt_shade,
    /// frame and console. A missing image returns null (warned once) and the table falls back to code-drawn shapes.
    /// Sprites are 100 pixels per unit, so with the canvas' reference 100 pixels per unit one texel is one canvas unit.
    /// </summary>
    public static class TableArt
    {
        const string ResourceFolder = "Table/";
        static readonly Dictionary<string, Sprite> Cache = new Dictionary<string, Sprite>();

        public static Sprite Get(string name)
        {
            Sprite cached;
            if (Cache.TryGetValue(name, out cached))
            {
                // A cached "missing" entry is a real null (warn once); a sprite Unity destroyed (Play mode without
                // domain reload) compares equal to null without being a null reference: rebuild it.
                if (ReferenceEquals(cached, null) || cached != null) return cached;
                Cache.Remove(name);
            }

            Sprite sprite = null;
            var tex = Resources.Load<Texture2D>(ResourceFolder + name);
            if (tex != null)
            {
                // FullRect is required for Image.Type.Tiled.
                sprite = Sprite.Create(tex, new Rect(0f, 0f, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
                sprite.name = "Table_" + name;
            }
            else
            {
                Debug.LogWarning("[Manjong] Table image Resources/" + ResourceFolder + name + ".png not found, using the plain table.");
            }
            Cache[name] = sprite;
            return sprite;
        }
    }
}
